__NUXT_JSONP__("/it/feature", (function(a){return {data:[{details:{slug:"it",pageTitle:"Perchè scegliere MLI | Mentor Language Institute",pageDescription:"Dalla nostra apertura nel 2002, abbiamo aiutato più di 17000 studenti a migliorare le loro abilità comunicative in lingua Inglese.",section1:{title:"Perchè scegliere MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"5 motivi per scegliere Mentor Language Institute",description:["Dalla nostra apertura nel 2002, \u003Cb\u003Eabbiamo aiutato più di 17000 studenti\u003C\u002Fb\u003E a migliorare le loro abilità comunicative in lingua Inglese. Perchè le persone scelgono MLI nonostante la presenza di tantissime altre scuole nella città di Los Angeles? Abbiamo condotto un sondaggio tra gli studenti di MLI e le loro risposte sono di seguito riportate."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Periodo del sondaggio: Gennaio- Giugno 2017, 342 studenti"},section3:[{title:"No.1 : Prezzi ragionevoli",subtitle:"Ottimo prezzo! A partire da $209 a settimana. Le lezioni pomeridiane costano il 40% in meno rispetto alle lezioni mattutine!",description:["La ragione principale per cui gli studenti scelgono MLI è la convenienza.","Più a lungo decidi di studiare nella nostra scuola, minore sarà il prezzo che dovrai sostenere. Se ti iscrivi per un mese, il costo del tuo corso sarà di $1,220 = \u003Cb\u003E$305 a settimana\u003C\u002Fb\u003E. (questo prezzo è già conveniente), ma se ti iscrivi per l'intero anno scolastico (48 settimane), questo si riduce raggiungendo un totale di $10,032 annui ovvero = \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E $209 a settimana\u003C\u002Fspan\u003E. Ti invitiamo a confrontare i nostri prezzi con quelli delle altre scuole."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"Maggiori informazioni sui prezzi",link:"\u002Fit\u002Fprice"}]},{title:"No.2 : Ottime Location",subtitle:"Westwood e Hollywood: due famose aree di Los Angeles",description:["La nostra scuola si trova in due famose aree di Los Angeles, \u003Cb\u003EWestwood\u003C\u002Fb\u003E e \u003Cb\u003EHollywood\u003C\u002Fb\u003E. Gli studenti che frequentano MLI possono facilmente raggiungere con la metropolitana altre celebri aree, come Santa Monica e Downtown LA."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood Campus"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood Campus"}],links:[{icon:a,text:"Maggiori informazioni sul Campus in Westwood",link:"\u002Fit\u002Fwestwood"},{icon:a,text:"Maggiori informazioni sul Campus in Hollywood",link:"\u002Fit\u002Fhollywood"}]},{title:"No.3 : Ampia gamma di corsi di preparazione al College",subtitle:"Molti dei nostri studenti si iscrivono a UCLA e Santa Monica college dopo aver studiato in MLI.",description:["Offriamo corsi per la preparazione ai test più richiesti dai vari College come \u003Cb\u003ETOEFL®, IELTS™.\u003C\u002Fb\u003E . Molti studenti si iscrivono a \u003Cb\u003EUCLA, USC\u003C\u002Fb\u003E e \u003Cb\u003ESanta Monica College\u003C\u002Fb\u003E dopo aver studiato in MLI."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"Maggiori informazioni riguardo l'iscrizione al college",link:"\u002Fit\u002Fgoing-to-college"}]},{title:"No.4 : Orario flessibile",subtitle:"Corsi di mattina, pomeriggio e sera",description:["\u003Cb\u003EMLI fornisce 3 diverse opzioni per le lezioni\u003C\u002Fb\u003E. Gli studenti possono scegliere tra corsi di mattina, pomeriggio e sera."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"※Questi sono gli orari dei corsi offerti dal campus in Westwood. Per avere informazioni sugli orari dei corsi al campus in Hollywood, contattaci."},{title:"No.5 : Dormitorio",subtitle:"Gli studenti di MLI che decidono di optare per l'alloggio nel nostro dormitorio hanno l'opportunità di conoscere e condividere esperienze con studenti di nazionalità e culture diverse.",description:["Non solo organizziamo Programmi Homestay, ma offriamo anche la possibilità di alloggiare nei nostri dormitori. Con più di 40 camere nell'area di Los Angeles, i nostri dormitori si trovano nei pressi di ciascun campus. Molti studenti decidono di alloggiare in un dormitorio soprattutto se è la loro prima volta negli States."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Maggiori informazioni sugli alloggi",link:"\u002Fit\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:29.192Z",updatedAt:"2026-03-24T13:34:16.405Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));